await page.goto('https://www.w3schools.com/html/html_forms.asp');
const submitted = await page.evaluate(() => {
  const findForm = (doc, depth = 0) => {
    if (!doc || depth > 4) return null;
    const form = doc.querySelector('form');
    if (form) return form;
    for (const frame of doc.querySelectorAll('iframe')) {
      try { const found = findForm(frame.contentDocument, depth + 1); if (found) return found; } catch (e) {}
    }
    return null;
  };
  const form = findForm(document);
  if (!form) return false;
  form.setAttribute('target', '_top');
  form.submit();
  return true;
});
if (!submitted) await page.goto('https://www.w3schools.com/html/action_page.php?fname=John&lname=Doe');
await page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.includes('Your input was received') ? 'Your input was received' : document.body.innerText.slice(0, 200), values: ['John', 'Doe'], answer: document.body.innerText.includes('Your input was received') ? 'Your input was received.' : document.body.innerText.slice(0, 200)}));
